  den.aspects.deploy = {
    flake = {
      flake.deploy.nodes =
        lib.mapAttrs (name: host: {
          hostname = host.name;
          profiles.system = {
            user = "root";
            path =
              inputs.deploy-rs.lib.${host.system}.activate.nixos
              config.flake.nixosConfigurations.${name};
          };
        })
        (lib.foldl (acc: s: acc // den.hosts.${s}) { } (builtins.attrNames den.hosts));
    };
  };

  den.schema.flake.includes = [ den.aspects.deploy ];
}
```

