let
  myconf =
    { class, aspect-chain }:
    den.batteries.forward {
      each = lib.singleton true;
      fromClass = _: "myconf";
      intoClass = _: "nixos";              # target whose module system does the merge
      intoPath = _: [ "programs" "myconf" ];
      fromAspect = _: lib.head aspect-chain;
    };
in
