```nix
{ den, ... }:
let
  fwd = { host, user }: den.batteries.forward {
    each       = lib.singleton user;
    fromClass  = _: "myclass";
    intoClass  = _: host.class;
    intoPath   = _: [ "..." ];
    fromAspect = _: user.aspect;   # whose collected content to move
  };
